local BannerMaker = {}
local PRODUCTS = {
    linen_banner = { name = "Lneni transparent", linenCost = 2, time = 2, cost = 20, visibility = 8, prestige = 1, description = "Preprost lneni transparent z napisom." },
    painted_banner = { name = "Poslikani transparent", linenCost = 2, paintCost = 1, time = 3, cost = 60, visibility = 12, prestige = 3, description = "Poslikani transparent z emblematom." },
    silk_banner = { name = "Svileni transparent", silkCost = 2, paintCost = 1, time = 5, cost = 150, visibility = 16, prestige = 7, happiness = 1, description = "Svileni transparent za plemiče." },
    embroidered_banner = { name = "Vezeni transparent", silkCost = 2, threadCost = 1, paintCost = 1, time = 7, cost = 340, visibility = 20, prestige = 12, happiness = 2, description = "Vezeni transparent z grbom." },
    gold_thread_banner = { name = "Zlatorobni transparent", silkCost = 2, goldCost = 1, threadCost = 1, paintCost = 1, time = 9, cost = 720, visibility = 25, prestige = 22, happiness = 4, description = "Transparent z zlatimi nitmi za kralje." },
    royal_processional_banner = { name = "Kraljevski procesijski transparent", silkCost = 3, goldCost = 2, silverCost = 1, jewelCost = 1, threadCost = 2, paintCost = 2, time = 13, cost = 1800, visibility = 35, prestige = 50, happiness = 10, description = "Veliki procesijski transparent z dragulji za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Transparentarska delavnica", cost = { gold = 240, wood = 110 }, upkeep = 6, qualityBonus = 5 },
    painting_room = { name = "Slikalnica", cost = { gold = 750, wood = 220, stone = 200, paint = 6 }, upkeep = 18, qualityBonus = 18 },
    embroidery_room = { name = "Vezenilnica", cost = { gold = 1700, wood = 280, stone = 350, silver = 25, thread = 8 }, upkeep = 40, qualityBonus = 30 },
    royal_banner_atelier = { name = "Kraljevski atelje transparentov", cost = { gold = 6500, wood = 500, stone = 700, gold = 50, silk = 20 }, upkeep = 120, qualityBonus = 55, prestigeBonus = 30 },
}
BannerMaker.linenStock = 14; BannerMaker.silkStock = 10; BannerMaker.paintStock = 10; BannerMaker.threadStock = 8; BannerMaker.goldStock = 6; BannerMaker.silverStock = 6; BannerMaker.jewelStock = 4
BannerMaker.productStock = {}; BannerMaker.buildings = {}; BannerMaker.maker = nil; BannerMaker.activeMaking = {}; BannerMaker.totalProducts = 0; BannerMaker.dayTimer = 0
function BannerMaker.init() BannerMaker.linenStock=14; BannerMaker.silkStock=10; BannerMaker.paintStock=10; BannerMaker.threadStock=8; BannerMaker.goldStock=6; BannerMaker.silverStock=6; BannerMaker.jewelStock=4; BannerMaker.productStock={}; BannerMaker.buildings={}; BannerMaker.maker=nil; BannerMaker.activeMaking={}; BannerMaker.totalProducts=0; BannerMaker.dayTimer=0; print("[BannerMaker] Royal Banner Maker System initialized (6 products, 4 buildings)") end
function BannerMaker.hireMaker(n,s) s=s or math.random(50,90); local c=450+s*10; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; BannerMaker.maker={name=n or ("Transparentar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Transparentar najet: %s (spretnost: %d)",BannerMaker.maker.name,s),"success") end; return true end
function BannerMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function BannerMaker.build(id) local ok,e=BannerMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(BannerMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function BannerMaker.getQualityBonus() local b=0; for _,bd in ipairs(BannerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function BannerMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.linenCost and BannerMaker.linenStock<(d.linenCost or 0) then return false,"Premalo lana" end; if d.silkCost and BannerMaker.silkStock<(d.silkCost or 0) then return false,"Premalo svile" end; if d.paintCost and BannerMaker.paintStock<(d.paintCost or 0) then return false,"Premalo barve" end; if d.threadCost and BannerMaker.threadStock<(d.threadCost or 0) then return false,"Premalo niti" end; if d.goldCost and BannerMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.silverCost and BannerMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.jewelCost and BannerMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if #BannerMaker.buildings==0 then return false,"Potrebna delavnica" end; if not BannerMaker.maker then return false,"Potreben transparentar" end; return true end
function BannerMaker.make(pt,qty) qty=qty or 1; local ok,e=BannerMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.linenCost then BannerMaker.linenStock=BannerMaker.linenStock-d.linenCost*qty end; if d.silkCost then BannerMaker.silkStock=BannerMaker.silkStock-d.silkCost*qty end; if d.paintCost then BannerMaker.paintStock=BannerMaker.paintStock-d.paintCost*qty end; if d.threadCost then BannerMaker.threadStock=BannerMaker.threadStock-d.threadCost*qty end; if d.goldCost then BannerMaker.goldStock=BannerMaker.goldStock-d.goldCost*qty end; if d.silverCost then BannerMaker.silverStock=BannerMaker.silverStock-d.silverCost*qty end; if d.jewelCost then BannerMaker.jewelStock=BannerMaker.jewelStock-d.jewelCost*qty end; local t=d.time; if BannerMaker.maker then t=math.max(1,t-math.floor(BannerMaker.maker.skill/12)) end; table.insert(BannerMaker.activeMaking,{id="banner_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,visibility=d.visibility or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function BannerMaker.completeMaking(m) local q=1.0+(BannerMaker.getQualityBonus()/100); if BannerMaker.maker then q=q+(BannerMaker.maker.skill/180) end; q=math.min(2.0,q); BannerMaker.productStock[m.productType]=(BannerMaker.productStock[m.productType] or 0)+m.quantity; BannerMaker.totalProducts=BannerMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if BannerMaker.maker then BannerMaker.maker.itemsMade=BannerMaker.maker.itemsMade+m.quantity; if math.random()<0.20 then BannerMaker.maker.skill=math.min(100,BannerMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Transparent izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"banner.completed",{productName=m.productName,prestige=m.prestige}) end end
function BannerMaker.update(dt) if not _G.state then return end; BannerMaker.dayTimer=BannerMaker.dayTimer+dt; if BannerMaker.dayTimer>=30 then BannerMaker.dayTimer=0; for i=#BannerMaker.activeMaking,1,-1 do local m=BannerMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then BannerMaker.completeMaking(m); table.remove(BannerMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(BannerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if BannerMaker.maker then tu=tu+12 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function BannerMaker.getStats() return {linenStock=BannerMaker.linenStock,silkStock=BannerMaker.silkStock,paintStock=BannerMaker.paintStock,threadStock=BannerMaker.threadStock,goldStock=BannerMaker.goldStock,silverStock=BannerMaker.silverStock,jewelStock=BannerMaker.jewelStock,productStock=BannerMaker.productStock,numBuildings=#BannerMaker.buildings,hasMaker=BannerMaker.maker~=nil,makerName=BannerMaker.maker and BannerMaker.maker.name or "—",makerSkill=BannerMaker.maker and BannerMaker.maker.skill or 0,activeMaking=#BannerMaker.activeMaking,totalProducts=BannerMaker.totalProducts} end
return BannerMaker
